//! The traceability id that ties one agent turn together.

use serde::{Deserialize, Serialize};

/// The id of one agent turn: generated by the host at `agent_prompt`,
/// carried into the sidecar's prompt envelope, into every tool exec, into
/// the CLI's audit rows, and into every ledger row from either path (the
/// spec's traceability contract). Serialises as its bare string so it
/// crosses process boundaries without a wrapper object.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct CorrelationId(String);

impl CorrelationId {
    /// Wraps an existing id string.
    pub fn new(value: String) -> Self {
        Self(value)
    }

    /// Generates a fresh correlation id (a v4 UUID, the spelling the kylins
    /// ledgers use for their prompt ids).
    pub fn generate() -> Self {
        Self(uuid::Uuid::new_v4().to_string())
    }

    /// The id string.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for CorrelationId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}
